// pyrepr.mjs — Python 风格的 repr() 字符串格式化工具
// 用于让 console.log 输出与 Python 的 print 结果逐字符一致。

// 复现 CPython repr(str) 的规则：
//  - 默认使用单引号包裹；
//  - 若字符串含单引号但不含双引号，则改用双引号包裹；
//  - 转义反斜杠、\n、\r、\t 及不可打印字符。
export function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

// 通用 repr：支持 string / tuple(数组且标记) / list
export function repr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (value instanceof PyTuple) {
    const inner = value.items.map(repr);
    // Python 单元素元组有尾随逗号: ('a',)
    return '(' + inner.join(', ') + (inner.length === 1 ? ',' : '') + ')';
  }
  if (Array.isArray(value)) {
    return '[' + value.map(repr).join(', ') + ']';
  }
  return String(value);
}

// 用于区分 Python 的 tuple 与 list 的轻量包装类型
export class PyTuple {
  constructor(...items) {
    this.items = items;
  }
}

export function pyTuple(...items) {
  return new PyTuple(...items);
}

// 复现 Python list 的 repr，如 ['y', 'z'] 或 [('x', 'z')]
export function reprList(arr) {
  return repr(arr);
}

