// orderedMultiDict.mjs — 复现 boltons.dictutils.OMD(OrderedMultiDict) 的可观察行为
import { repr, reprStr, pyTuple } from './pyrepr.mjs';

// 有序多值字典：
//  - add(k, v) 追加键值对，同一键可持有多个值，返回 undefined(Python 中为 None)
//  - getlist(k) 返回该键的所有值列表
//  - keys() 返回按首次插入顺序排列的唯一键
//  - items() 返回每个键与其最近(最后)一个值组成的键值对
export class OrderedMultiDict {
  constructor() {
    // 保持所有插入的键值对(含重复键)，保证顺序
    this._pairs = [];
  }

  add(key, value) {
    this._pairs.push([key, value]);
    return undefined;
  }

  getlist(key) {
    return this._pairs.filter(([k]) => k === key).map(([, v]) => v);
  }

  keys() {
    const seen = new Set();
    const result = [];
    for (const [k] of this._pairs) {
      if (!seen.has(k)) {
        seen.add(k);
        result.push(k);
      }
    }
    return result;
  }

  items() {
    // 每个键只保留最后一次出现的值
    const lastIndex = new Map();
    this._pairs.forEach(([k], i) => lastIndex.set(k, i));
    const seen = new Set();
    const result = [];
    for (const [k] of this._pairs) {
      if (!seen.has(k)) {
        seen.add(k);
        result.push([k, this._pairs[lastIndex.get(k)][1]]);
      }
    }
    return result;
  }

  // 对应 Python 中 print(omd) 的 repr 形式:
  //   OrderedMultiDict([('x', 'y'), ('x', 'z')])
  toString() {
    const inner = this._pairs
      .map(([k, v]) => '(' + reprStr(k) + ', ' + reprStr(v) + ')')
      .join(', ');
    return 'OrderedMultiDict([' + inner + '])';
  }

  // list(omd.items()) 的 repr: [('x', 'z')]
  itemsRepr() {
    return repr(this.items().map(([k, v]) => pyTuple(k, v)));
  }
}

