// argparse.mjs — 极简版 argparse：仅复现本任务所需的命令行解析行为
// 支持 --name value 与 --name=value 两种形式、必填参数校验、-h/--help。
// 错误信息格式对齐 Python argparse，退出码一致(错误为 2，帮助为 0)。
import { basename } from 'node:path';

export class ArgumentParser {
  constructor(options = {}) {
    // Python argparse 的 prog 取 sys.argv[0] 的 basename
    this.prog = options.prog || basename(process.argv[1] || 'program');
    this._args = []; // { name, metavar, required, help }
  }

  addArgument(name, { required = false } = {}) {
    const metavar = name.replace(/^--/, '').toUpperCase();
    this._args.push({ name, metavar, required });
  }

  _usage() {
    const parts = this._args.map((a) => `${a.name} ${a.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  _error(message) {
    process.stderr.write(this._usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _printHelp() {
    let out = this._usage() + '\n\noptions:\n';
    out += '  -h, --help  show this help message and exit\n';
    for (const a of this._args) {
      out += `  ${a.name} ${a.metavar}\n`;
    }
    process.stdout.write(out);
    process.exit(0);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const byName = new Map(this._args.map((a) => [a.name, a]));
    const values = {};
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this._printHelp();
      }
      let name = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const idx = token.indexOf('=');
        name = token.slice(0, idx);
        inlineValue = token.slice(idx + 1);
      }
      const spec = byName.get(name);
      if (!spec) {
        extras.push(token);
        continue;
      }
      if (inlineValue !== null) {
        values[name] = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || (next.startsWith('-') && byName.has(next))) {
          this._error(`argument ${name}: expected one argument`);
        }
        values[name] = next;
        i++;
      }
    }

    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const missing = this._args.filter((a) => a.required && !(a.name in values));
    if (missing.length > 0) {
      this._error(
        'the following arguments are required: ' +
          missing.map((a) => a.name).join(', ')
      );
    }

    return values;
  }
}

