// test6.mjs — 入口测试文件，对齐 /workspace/dataset/test6.py 的行为
import { ArgumentParser } from './argparse.mjs';
import { OrderedMultiDict } from './orderedMultiDict.mjs';
import { reprList } from './pyrepr.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', { required: true });
parser.addArgument('--b', { required: true });
parser.addArgument('--c', { required: true });
const args = parser.parseArgs();

const omd = new OrderedMultiDict(); // 创建有序多值字典
console.log(omd.toString());
omd.add(args['--a'], args['--b']); // 添加键值对（add方法返回None）
console.log(omd.toString());
omd.add(args['--a'], args['--c']); // 添加相同键的第二个值
console.log(omd.toString());
const result1 = omd.getlist(args['--a']); // 获取键的所有值
console.log(reprList(result1));
const result2 = omd.keys(); // 获取所有键
console.log(reprList(result2));
const result3 = omd.items(); // 获取所有键值对
console.log(omd.itemsRepr(result3));

